-export async function listTools(){return []}export async function callTool(){return {content:[]}}
+const MODES = ['uppercase', 'lowercase', 'slug'];
+const ALLOWED_ARGS = ['text', 'mode', 'trim'];
+
+const TEXT_TRANSFORM_TOOL = {
+  name: 'text_transform',
+  description:
+    'Transform text by changing its case (uppercase or lowercase) or by ' +
+    'generating a URL-friendly slug. An optional trim flag (default true) ' +
+    'removes surrounding whitespace.',
+  inputSchema: {
+    type: 'object',
+    properties: {
+      text: { type: 'string', description: 'The text to transform.' },
+      mode: {
+        type: 'string',
+        enum: MODES,
+        description: 'Transform mode: "uppercase", "lowercase", or "slug".',
+      },
+      trim: {
+        type: 'boolean',
+        default: true,
+        description: 'Whether to trim surrounding whitespace. Defaults to true.',
+      },
+    },
+    required: ['text', 'mode'],
+    additionalProperties: false,
+  },
+};
+
+function applyTransform(text, mode, trim) {
+  if (mode === 'slug') {
+    let out = text.toLowerCase();
+    if (trim) out = out.trim();
+    out = out.replace(/[^a-z0-9]+/g, '-');
+    out = out.replace(/^-+|-+$/g, '');
+    return out;
+  }
+  let out = mode === 'uppercase' ? text.toUpperCase() : text.toLowerCase();
+  if (trim) out = out.trim();
+  return out;
+}
+
+export async function listTools() {
+  return [TEXT_TRANSFORM_TOOL];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'text_transform') {
+    throw new Error(`Unknown tool: ${String(name)}`);
+  }
+
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object.');
+  }
+
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.includes(key)) {
+      throw new Error(`Unexpected argument: "${key}". Allowed arguments are: ${ALLOWED_ARGS.join(', ')}.`);
+    }
+  }
+
+  const { text, mode, trim = true } = args;
+
+  if (typeof text !== 'string') {
+    throw new Error('Argument "text" is required and must be a string.');
+  }
+  if (typeof mode !== 'string' || !MODES.includes(mode)) {
+    throw new Error(`Argument "mode" is required and must be one of: ${MODES.join(', ')}.`);
+  }
+  if (trim !== undefined && typeof trim !== 'boolean') {
+    throw new Error('Argument "trim" must be a boolean.');
+  }
+
+  const result = applyTransform(text, mode, trim);
+  return { content: [{ type: 'text', text: result }] };
+}
